-- Administrator identity and control-plane data only; no visitor identities or behavior history.
CREATE TABLE IF NOT EXISTS admin_settings (id INTEGER PRIMARY KEY CHECK(id=1), initialized INTEGER NOT NULL DEFAULT 0, body TEXT NOT NULL CHECK(json_valid(body)), revision TEXT NOT NULL);
INSERT OR IGNORE INTO admin_settings(id,body,revision) VALUES(1,'{"name":"JevSense","model":"jev-1.14.0","dailyRequestBudget":1000,"maxConcurrent":10}',lower(hex(randomblob(16))));
CREATE TABLE IF NOT EXISTS admin_users (id TEXT PRIMARY KEY, email TEXT NOT NULL COLLATE NOCASE UNIQUE, display_name TEXT NOT NULL, global_role TEXT NOT NULL CHECK(global_role IN ('superuser','member')), status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','disabled')), version INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS admin_credentials (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES admin_users(id) ON DELETE CASCADE, public_key TEXT NOT NULL, counter INTEGER NOT NULL DEFAULT 0, transports TEXT NOT NULL DEFAULT '[]', device_type TEXT, backed_up INTEGER NOT NULL DEFAULT 0, label TEXT NOT NULL, created_at INTEGER NOT NULL, last_used_at INTEGER);
CREATE INDEX IF NOT EXISTS admin_credentials_user ON admin_credentials(user_id);
CREATE TABLE IF NOT EXISTS admin_sessions (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES admin_users(id) ON DELETE CASCADE, user_version INTEGER NOT NULL, csrf TEXT NOT NULL, created_at INTEGER NOT NULL, last_seen INTEGER NOT NULL, expires_at INTEGER NOT NULL, authenticated_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS admin_sessions_user ON admin_sessions(user_id);
CREATE TABLE IF NOT EXISTS admin_challenges (id TEXT PRIMARY KEY, challenge TEXT NOT NULL, browser_hash TEXT NOT NULL, kind TEXT NOT NULL, context TEXT NOT NULL CHECK(json_valid(context)), expires_at INTEGER NOT NULL, used INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS admin_memberships (user_id TEXT NOT NULL REFERENCES admin_users(id) ON DELETE CASCADE, site_id TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('admin','editor','viewer')), PRIMARY KEY(user_id,site_id));
CREATE TABLE IF NOT EXISTS admin_sites (id TEXT PRIMARY KEY, body TEXT NOT NULL CHECK(json_valid(body)), revision TEXT NOT NULL);
INSERT OR IGNORE INTO admin_sites(id,body,revision) SELECT json_extract(value,'$.id'),json(value),lower(hex(randomblob(16))) FROM json_each((SELECT body FROM app_config WHERE id=1),'$.sites');
CREATE TABLE IF NOT EXISTS admin_drafts (site_id TEXT NOT NULL, campaign_id TEXT NOT NULL, body TEXT NOT NULL CHECK(json_valid(body)), revision TEXT NOT NULL, base_hash TEXT NOT NULL, PRIMARY KEY(site_id,campaign_id));
CREATE TABLE IF NOT EXISTS admin_invitations (token_hash TEXT PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN ('invite','recovery')), email TEXT NOT NULL COLLATE NOCASE, site_id TEXT, role TEXT CHECK(role IN ('admin','editor','viewer')), target_user TEXT, created_by TEXT NOT NULL REFERENCES admin_users(id), created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, used INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS admin_invitation_lookup ON admin_invitations(site_id,email);
CREATE TABLE IF NOT EXISTS admin_recovery_codes (code_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES admin_users(id) ON DELETE CASCADE, used INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS admin_preview_tickets (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES admin_users(id), site_id TEXT NOT NULL, campaign_id TEXT NOT NULL, origin TEXT NOT NULL, path TEXT NOT NULL, revision TEXT NOT NULL, expires_at INTEGER NOT NULL, used INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS admin_preview_modules (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES admin_users(id), site_id TEXT NOT NULL, origin TEXT NOT NULL, source TEXT NOT NULL, expires_at INTEGER NOT NULL, used INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS admin_audit (id TEXT PRIMARY KEY, actor_id TEXT, action TEXT NOT NULL, site_id TEXT, target_id TEXT, created_at INTEGER NOT NULL);
CREATE TRIGGER IF NOT EXISTS admin_last_superuser_update BEFORE UPDATE OF global_role,status ON admin_users WHEN OLD.global_role='superuser' AND OLD.status='active' AND (NEW.global_role<>'superuser' OR NEW.status<>'active') AND NOT EXISTS(SELECT 1 FROM admin_users WHERE id<>OLD.id AND global_role='superuser' AND status='active') BEGIN SELECT RAISE(ABORT,'last_superuser'); END;
CREATE TRIGGER IF NOT EXISTS admin_last_superuser_delete BEFORE DELETE ON admin_users WHEN OLD.global_role='superuser' AND OLD.status='active' AND NOT EXISTS(SELECT 1 FROM admin_users WHERE id<>OLD.id AND global_role='superuser' AND status='active') BEGIN SELECT RAISE(ABORT,'last_superuser'); END;
CREATE TRIGGER IF NOT EXISTS admin_last_passkey BEFORE DELETE ON admin_credentials WHEN EXISTS(SELECT 1 FROM admin_users WHERE id=OLD.user_id AND status='active') AND (SELECT count(*) FROM admin_credentials WHERE user_id=OLD.user_id)=1 BEGIN SELECT RAISE(ABORT,'last_passkey'); END;
CREATE TRIGGER IF NOT EXISTS admin_legacy_config_locked BEFORE UPDATE ON app_config WHEN (SELECT initialized FROM admin_settings WHERE id=1)=1 BEGIN SELECT RAISE(ABORT,'legacy_config_locked'); END;
